insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,sumber_pdf,halaman,kalimat,kalimat_ruby,kosakata) values
('宿泊分野','許可を受けずに宿泊施設を営業した場合どうなりますか？','["違法となる", "問題ない", "届け出だけでよい", "罰則はない"]'::jsonb,0,'旅館業法の許可がない営業は違法です。',101,'00 · 旅館業法 (undang-undang usaha penginapan)','2号',6,'許可なしに宿泊施設を運営することは違法です。 りょかんぎょうほう おも ないよう とお い か りょかんぎょう と ど う ふ け ん ち じ いとな ほけんじょちょう きょか ひつよう きょか うんえい いほう しゅくはくしせつ きょか え しせつ こうぞう',null,'[]'::jsonb),
('宿泊分野','施設の基準に含まれないものはどれですか？','["宿泊者の年収", "客室の広さ", "換気", "採光"]'::jsonb,0,'構造設備の基準は客室の広さ・換気・採光・トイレ・洗面などです。',102,'00 · 旅館業法 (undang-undang usaha penginapan)','2号',6,'しせつ きじゅん きょか しゅとく ２. 施設の基準 許可を得るためには施設の構造設備が一定の基準を満たしている必要があります。 これには、客室の広さ、換気、採光、トイレ、洗面設備などが含まれます。',null,'[]'::jsonb),
('宿泊分野','衛生管理として行うことはどれですか？','["定期的な清掃・消毒・害虫駆除", "客室の改装", "料金の値上げ", "予約数の分析"]'::jsonb,0,'衛生管理は清掃・消毒・害虫駆除などです。',103,'00 · 旅館業法 (undang-undang usaha penginapan)','2号',6,'３. 衛生管理 宿泊施設は衛生的な環境を維持するために、定期的な清掃や消毒、害虫駆除などの衛 生管理を行う必要があります。また、宿泊者が安全に利用できるように、防火対策や 避難経路の確保も求められます。',null,'[]'::jsonb),
('宿泊分野','避難訓練について正しいのはどれですか？','["実施が奨励されている", "禁止されている", "年に一度は義務", "届け出は不要"]'::jsonb,0,'宿泊者が安全に避難できるよう避難訓練の実施が奨励されています。',104,'00 · 旅館業法 (undang-undang usaha penginapan)','2号',6,'また、宿泊者が安全に避難できるよう、避難訓練を実施することも奨励されています。 ６. 宿泊者名簿の作成と保管 宿泊施設は、宿泊者の氏名、住所、職業、宿泊日数などを記録した宿泊者名簿を作成し、 一定期間保管する義務があります。',null,'[]'::jsonb),
('宿泊分野','宿泊施設を監督するのはどこですか？','["保健所や自治体の担当部門", "旅行会社", "消防署のみ", "観光協会"]'::jsonb,0,'保健所や自治体が監督・指導を行い、違反には是正指導や罰則があります。',105,'00 · 旅館業法 (undang-undang usaha penginapan)','2号',6,'７. 監督と指導 保健所や自治体の担当部門が、宿泊施設の監督と指導を行います。定期的な検査や立 入調査を実施し、違反があった場合は是正指導や罰則が科されることがあります。 ８. 違反に対する罰則 旅館業法に違反した場合、営業停止命令や許可取り消し、罰金などの罰則が科される こと',null,'[]'::jsonb),
('宿泊分野','予約の問い合わせを受けたとき、最初に確認することはどれですか？','["希望日に空室があるか", "お客様の年齢", "支払い方法", "食事の好み"]'::jsonb,0,'希望日に部屋が空いているかを確認し、空室がなければ予約は受けられません。',106,'01 · フロント業務 (resepsionis)','2号',10,'お客様からの電話、メール、ウェブサイトなどを通じた予約の問い合わせについて、お客 様の宿泊希望日に部屋が空いているかどうかを確認する必要があります。もし部屋が空い ていない場合お客様が予約すること はできません。',null,'[]'::jsonb),
('宿泊分野','宿泊予定日・氏名・人数などを事前に聞く目的はどれですか？','["ノーショー（無連絡キャンセル）の防止", "売上の記録", "SNS投稿", "清掃計画"]'::jsonb,0,'事前確認でノーショーを防ぎ、おもてなしの準備をします。',107,'01 · フロント業務 (resepsionis)','2号',12,'上記を事前にお聞きし、お客様に宿泊予定日に必ず来ていただくこと（ノーショーの防止） をお約束するとともに、宿泊施設として最高のおもてなしをお客様に提供する準備ができ るようにします。',null,'[]'::jsonb),
('宿泊分野','客室での対応として正しいのはどれですか？','["許可なく客室に入らない", "合鍵で自由に入る", "清掃中なら入ってよい", "ノックは不要"]'::jsonb,0,'お客様の許可なく客室に入ってはいけません。',108,'01 · フロント業務 (resepsionis)','2号',20,'その際には、必ずドアをノックす るか呼び鈴を鳴らし、お客様が「入ってください」という許可をもらってから客室に入ら なければいけません。お客様の許可なく、むやみに客室内に入っていってはいけません。',null,'[]'::jsonb),
('宿泊分野','会計（キャッシャー）業務の内容はどれですか？','["請求明細書を発行して料金を請求する", "部屋を清掃する", "予約を受ける", "料理を運ぶ"]'::jsonb,0,'館内利用・宿泊料金・サービス料・税を明細にして請求します。',109,'01 · フロント業務 (resepsionis)','2号',22,'などの確認 会計またはキャッシャーと呼ばれる業務で、主な内容として館内利用、宿泊料金、サービ ス料、税など、お客様にご請求する内容を記載した請求明細書を発行してお客様にお見せ し、料金を請求します。',null,'[]'::jsonb),
('宿泊分野','宿泊プランを企画するときに最初に決めることはどれですか？','["ターゲットとする客層", "清掃の順番", "シフト表", "領収書の様式"]'::jsonb,0,'客層を定め、ニーズを理解してプランを立案します。',110,'02 · 企画・広報 (perencanaan & promosi)','2号',25,'ラン、日帰りプラン、ランチビュッフェプ ランといったお客様に喜んでいただけるような新プランの開発やイベントを設計する仕事 です。その際には、ターゲットとする客層を正しく設定し、マーケティングによりその客 層のニーズをしっかりと理解し、適切なプランを企画立案していくことが重要です。',null,'[]'::jsonb),
('宿泊分野','最敬礼の角度はおよそどれですか？','["約45°", "約15°", "約30°", "約60°"]'::jsonb,0,'最敬礼は約45°で、お詫びや深い感謝の場面で使います。',111,'03 · 接客 (layanan tamu)','2号',38,'して、様々な場 面で最も使います 約30°前傾 敬礼 普通礼 ② お客様がお帰りの際にお見送りする時、お客様に お詫びする時などに使います 約45°前傾 最敬礼 ③ また、接客するお客様に敬意を表すのがおじぎです。',null,'[]'::jsonb),
('宿泊分野','お客様とすれ違うときの正しい対応はどれですか？','["通過するまで立ち止まって会釈する", "早足で追い越す", "目を合わせない", "声をかけずに通り過ぎる"]'::jsonb,0,'すれ違う際は一度立ち止まり会釈します。',112,'03 · 接客 (layanan tamu)','2号',40,'③お客様とすれ違う時には、お客様が前を通過するまで一度立ち止まって会釈します。 ④お客様に呼び止められた時には、「お呼びでございますか」と返事をします。 ⑤お客様からお預かりした手荷物を客室まで運ぶ際には、丁寧な取り扱いを心がけ客室内 までお持ちします。',null,'[]'::jsonb),
('宿泊分野','お客様に呼び止められたときの返事はどれですか？','["「お呼びでございますか」", "「何ですか」", "「ちょっと待って」", "無言で近づく"]'::jsonb,0,'「お呼びでございますか」と返事をします。',113,'03 · 接客 (layanan tamu)','2号',40,'④お客様に呼び止められた時には、「お呼びでございますか」と返事をします。 ⑤お客様からお預かりした手荷物を客室まで運ぶ際には、丁寧な取り扱いを心がけ客室内 までお持ちします。 ⑥地図を使ってお客様に道案内をする際には、手のひらを上に向け4 本の指をそろえてご 案内します。',null,'[]'::jsonb),
('宿泊分野','食中毒の原因として正しいものはどれですか？','["ノロウイルスやサルモネラ属菌", "花粉", "紫外線", "騒音"]'::jsonb,0,'ノロウイルス・カンピロバクター・サルモネラなどが主な原因です。',114,'04 · レストランサービス','2号',54,'食中毒の主な要因は細菌やウイルスや寄 生虫が原因で、具体的には、ノロウイルス、カンピロバクター、サルモネラ属菌などがあ げられます。特にノロウイルスは非常に強い感染力を持ち、毎年11 ～2 月の冬場にかけて 多くの患者が発生します。',null,'[]'::jsonb),
('宿泊分野','「配膳」の意味はどれですか？','["料理や飲み物をテーブルに運び提供すること", "食器を洗うこと", "会計すること", "予約を取ること"]'::jsonb,0,'配膳 = membawa dan menyajikan makanan/minuman ke meja.',115,'04 · レストランサービス','2号',56,'9. 専門用語 ・シルバー ナイフやフォークなど ・カスターセット テーブル上の調味料などのセット ・配膳 料理や飲み物をテーブルに運び適切に提供すること ・ウェルカムドリンク レストランのコースの最初などに提供する歓迎の意を示す飲み物 ・メインディッシュ 食事の中心となる主要な料理 ・ブッフェ料理 多種多様な料理が並び、お客様が好きな料理を選んで取り分ける食事スタ',null,'[]'::jsonb),
('宿泊分野','「ブッフェ料理」とはどのようなスタイルですか？','["好きな料理を選んで取り分ける", "コースで順番に運ばれる", "部屋まで届けられる", "テイクアウトのみ"]'::jsonb,0,'ブッフェは多種多様な料理を自分で選ぶスタイルです。',116,'04 · レストランサービス','2号',56,'ースの最初などに提供する歓迎の意を示す飲み物 ・メインディッシュ 食事の中心となる主要な料理 ・ブッフェ料理 多種多様な料理が並び、お客様が好きな料理を選んで取り分ける食事スタイルで、 一般的にホテルの朝食などに多い ・アラカルト メニューから個々の料理を選んで注文するスタイル ・ソムリエ ワインに関する専門的知識を持ち、お客様に最適なワインの選択を提案する専門職 ・テイクアウト 店内で食事をせず',null,'[]'::jsonb),
('宿泊分野','急病人や火災のとき、連絡する番号はどれですか？','["119", "110", "104", "177"]'::jsonb,0,'火災・急病人は119番（消防・救急）に連絡します。',117,'05 · 安全衛生管理・その他','2号',59,'救急車を手配する必 要があると判断した場合は、速やかに消防署（119 番）に連絡をすること。その際、 急病人の症状や年齢、性別などをできるだけ詳しく伝えることが重要であること ・病気や伝染病に関してその危険性や感染の広がり、正確な対応方法について必要な知 識を得て、理解していること ・持ち主がわからない不審物がな',null,'[]'::jsonb),
('宿泊分野','宿泊施設の環境対応として正しいのはどれですか？','["省エネやゴミ削減などSDGsの取り組み", "使い捨てを増やす", "水を多く使う", "冷暖房を常時最大"]'::jsonb,0,'省エネ・節水・ゴミ削減など環境にやさしい取り組みが重要です。',118,'05 · 安全衛生管理・その他','2号',58,'安全衛生管理その他基礎知識について 3.従業員の安全確保について 4.衛生管理について 5.施設管理について 2.お客様の安全確保について 6.環境対応について 宿泊施設におけるリスクの 1. 理解と回避について そうてい りょかん りかい にちじょうぎょうむ なか つね かいひ ぼうし はか かさい じしん さい がい しょう まんいち さい じんそく れいせい たいおう じゅうよう あ ん ぜ',null,'[]'::jsonb),
('宿泊分野','施設管理で気をつけることはどれですか？','["小さな不備を放置しない", "故障はそのままにする", "点検は年1回だけ", "利用者の声は無視する"]'::jsonb,0,'小さな不備が大きな事故につながるため、点検・修繕が欠かせません。',119,'05 · 安全衛生管理・その他','2号',63,'5.施設管理について 宿泊施設には様々な施設、設備、機器等がありますが、小さな不備が大きな事故につなが る可能性があります。そうしたことのないよう施設管理を適切に行うことがとても重要で す。',null,'[]'::jsonb),
('宿泊分野','宿泊施設の衛生管理で防ぐべきものはどれですか？','["食中毒や感染症", "予約の増加", "客室の広さ", "料金の変動"]'::jsonb,0,'食中毒・感染症を出さないための衛生管理が重要です。',120,'05 · 安全衛生管理・その他','2号',58,'細を説明していきます 安 全 衛 生 管 理 そ の 他 基 礎 知 識 安全衛生管理その他基礎知識について 3.従業員の安全確保について 4.衛生管理について 5.施設管理について 2.お客様の安全確保について 6.環境対応について 宿泊施設におけるリスクの 1. 理解と回避について そうてい りょかん りかい にちじょうぎょうむ なか つね かいひ ぼうし はか かさい じしん さい がい し',null,'[]'::jsonb),
('宿泊分野','安全対策で「お客様の安全」と並んで重要なものはどれですか？','["従業員自身の安全", "売上の最大化", "SNSの更新", "備品の購入"]'::jsonb,0,'お客様と同時に従業員の安全確保も重要です。',121,'05 · 安全衛生管理・その他','2号',58,'からフローチャートにそって、詳細を説明していきます 安 全 衛 生 管 理 そ の 他 基 礎 知 識 安全衛生管理その他基礎知識について 3.従業員の安全確保について 4.衛生管理について 5.施設管理について 2.お客様の安全確保について 6.環境対応について 宿泊施設におけるリスクの 1. 理解と回避について そうてい りょかん りかい にちじょうぎょうむ なか つね かいひ ぼうし はか',null,'[]'::jsonb),
('宿泊分野（1号）','予約管理の業務に含まれるものはどれですか？','["問い合わせ対応とキャンセル・変更の調整", "客室の清掃", "料理の提供", "駐車場の管理"]'::jsonb,0,'予約情報の管理と、キャンセル・変更の調整が中心です。',101,'1号 · 01 · フロント業務','1号',6,'1. チェックイン業務 2. 館内でのお客様対応と 情報提供 3. チェックアウト･会計業務 4. 1.予約管理 予約管理は、お客様からの予約の問い合わせへの正しい対応、お客様からのリクエストに 応じた予約のキャンセルや変更の調整など、お客様が宿泊施設に宿泊するための予約情報 を管理する業務です。',null,'[]'::jsonb),
('宿泊分野（1号）','予約を受けるときに必ず行うことはどれですか？','["個人情報を聞き適切に管理する", "SNSに載せる", "同僚に共有する", "メモを捨てる"]'::jsonb,0,'個人情報は正確に聞き取り、適切に管理します。',102,'1号 · 01 · フロント業務','1号',8,'. お客様情報の確認 C. 予約のキャンセル、調整など お客様から電話、メール、ウェブサイトなどを通じて予約を受ける時には、お客様ご自身 の個人情報をお聞きし、適切に管理する必要があります。',null,'[]'::jsonb),
('宿泊分野（1号）','フロントで重要な姿勢として正しいのはどれですか？','["正しい礼儀作法（言葉遣い）を身につける", "早口で話す", "敬語は使わない", "無表情を保つ"]'::jsonb,0,'宿泊施設の印象を決めるため、正しい言葉遣いと礼儀作法が重要です。',103,'1号 · 01 · フロント業務','1号',5,'宿泊施 設そのものの印象を決めることにつながる重要な業務ですので、 正しい礼儀作法（言葉遣いなど）を身につけることが重要です。 しゅくはくぎょう よ しごと しゅくはくしせつ きゃくさま でむか みおく お てつづ たんとう きゃくさま しゅくはくしせつ とうちゃく しゅく はくしせつ しゅっぱつ あいだ きゃくさま たいおう しゅ',null,'[]'::jsonb),
('宿泊分野（1号）','宿泊プランを企画するときに最初に決めることはどれですか？','["ターゲットとする客層", "清掃の順番", "シフト", "領収書の形式"]'::jsonb,0,'客層を設定し、ニーズを理解してプランを立案します。',104,'1号 · 02 · 企画・広報','1号',20,'ラン、日帰りプラン、ランチビュッフェプ ランといったお客様に喜んでいただけるような新プランの開発やイベントを設計する仕事 です。その際には、ターゲットとする客層を正しく設定し、マーケティングによりその客 層のニーズをしっかりと理解し、適切なプランを企画立案していくことが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','広報（情報発信）の目的として正しいのはどれですか？','["自社を関係者に知ってもらい良い関係を作る", "売上を隠す", "社員を減らす", "客室を減らす"]'::jsonb,0,'旅行者・取引先・株主・従業員・地域住民などに知ってもらい関係を作ります。',105,'1号 · 02 · 企画・広報','1号',23,'情報発信をすることで、自社のことを、ステークホルダー（旅行者、関係取引先、株主、 自社の従業員、地域住民など）に良く知ってもらい、良い関係を作ることができます。また、 自社の企業としての価値をあげることや、自社のことをより多くの人に知ってもらうこ とにつながります。',null,'[]'::jsonb),
('宿泊分野（1号）','接客の基本とされるものはどれですか？','["あいさつ", "会計", "清掃", "予約"]'::jsonb,0,'あいさつは接客の基本です。',106,'1号 · 03 · 接客','1号',28,'接客について 1.あいさつ 2.接客の基本姿勢とおじぎ 3.接客の際の話し方 4.具体的な接客方法 5.電話対応 6.クレーム（苦情）対応 あいさつは接客の基本です。お客様にあいさつをすると、お客様は気持ちよく滞在す ることができます。',null,'[]'::jsonb),
('宿泊分野（1号）','最敬礼の角度はおよそどれですか？','["約45°", "約15°", "約30°", "約90°"]'::jsonb,0,'最敬礼は約45°です。',107,'1号 · 03 · 接客','1号',31,'して、様々な場 面で最も使います 約30°前傾 敬礼 普通礼 ② お客様がお帰りの際にお見送りする時、お客様に お詫びする時などに使います 約45°前傾 最敬礼 ③ また、接客するお客様に敬意を表すのがおじぎです。',null,'[]'::jsonb),
('宿泊分野（1号）','お客様と話すときの話し方として正しいのはどれですか？','["敬語で丁寧に話す", "タメ口で話す", "早口でまくし立てる", "話をさえぎる"]'::jsonb,0,'敬語を使い、聞き取りやすく話します。',108,'1号 · 03 · 接客','1号',32,'尊敬語 謙譲語 目上の人や自分より立場が 上の人をうやまい相手を立 てる気持ちを表します 自分がへりくだることで相 手を立て敬意を表します 「この料理はおいしいです」 「旅館へ行きます」などの ように語尾に「です」 「ます」 「ございます」を付けたり、 「お料理',null,'[]'::jsonb),
('宿泊分野（1号）','電話で注文を受けるとき、間違いを防ぐためにすることはどれですか？','["注文内容を復唱して確認する", "すぐ切る", "メモを取らない", "後で確認する"]'::jsonb,0,'注文内容を繰り返して確認します。',109,'1号 · 01 · フロント業務','1号',14,'また、ご滞在中のお客様から料理や飲み物をお部屋に届けるルームサービスの注文を電話 で受ける場合は、ご注文内容に間違いがないかご注文内容を繰り返すなどして、しっかり 確認することが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','和食の特徴として正しいのはどれですか？','["提供方法や食べ方に独自の文化がある", "洋食と同じ配膳", "すべてビュッフェ", "必ず部屋食"]'::jsonb,0,'和食には独自の提供方法とマナーがあります。',110,'1号 · 04 · レストランサービス','1号',39,'3.食事･ドリンクの提供 食事のルールやマナーは、国や習慣によって異なります。日本では、和食の提供方法や食 べ方について独自の文化があります。 次のページから、和食と洋食を説明します。',null,'[]'::jsonb),
('宿泊分野（1号）','洋食の提供の基本として正しいのはどれですか？','["料理は左側から提供する", "右側から提供する", "後ろから提供する", "上から置く"]'::jsonb,0,'洋食は基本的に左側から提供します。',111,'1号 · 04 · レストランサービス','1号',39,'洋食では、基本的に はお料理は左側から提供します。お飲み物は右側から提供します。 また、ドリンクの提供時にグラスを持つ際は、コップの半分よりも下を持つようにします。 テーブルに置く時には、音を立てないように気を付けます。',null,'[]'::jsonb),
('宿泊分野（1号）','「配膳」の意味はどれですか？','["料理や飲み物をテーブルに運び提供すること", "会計をすること", "部屋を掃除すること", "予約を取ること"]'::jsonb,0,'配膳 = 運んで提供する作業です。',112,'1号 · 04 · レストランサービス','1号',44,'ルギーについて 6.安全衛生管理 7.専門用語 ・シルバー ナイフやフォークなど ・カスターセット テーブル上の調味料などのセット ・配膳 料理や飲み物をテーブルに運び適切に提供すること ・ウェルカムドリンク レストランのコースの最初などに提供する歓迎の意を示す飲み物 ・メインディッシュ 食事の中心となる主要な料理 ・ブッフェ料理 多種多様な料理が並び、お客様が好きな料理を選んで取り分ける食事スタ',null,'[]'::jsonb),
('宿泊分野（1号）','食物アレルギーで重い症状を何といいますか？','["アナフィラキシーショック", "ノーショー", "ブッフェ", "ウェルカムドリンク"]'::jsonb,0,'アナフィラキシーショックは呼吸困難など重い症状で、命に関わります。',113,'1号 · 04 · レストランサービス','1号',42,'症状がひどいときは、アナフィラキシーショックといい、 呼吸困難など重い症状が出て、適切な対応をしないと死にいたる場合があります。 一般的なアレルゲンとしては、卵・牛乳・ナッツ類・魚介類・小麦・大豆などが代表的です。',null,'[]'::jsonb),
('宿泊分野（1号）','レストランでの身だしなみで求められることはどれですか？','["清潔感", "派手なアクセサリー", "長い爪", "香水を強くつける"]'::jsonb,0,'レストラン接客では清潔感が求められます。',114,'1号 · 04 · レストランサービス','1号',38,'4. 食のルールやマナー 5. 食物アレルギーについて 6. 安全衛生管理 7. 専門用語 2.服装･身だしなみ レストランでの接客の際は、清潔感が求められます。 具体的には、 などが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','施設管理で正しい考え方はどれですか？','["小さな不備が大きな事故につながる", "故障は放置してよい", "点検は不要", "利用者の声は無視する"]'::jsonb,0,'小さな不備が大きな事故につながるため点検が重要です。',115,'1号 · 05 · 安全衛生管理','1号',46,'ートにそって、詳細を説明していきます リスクの理解と回避について 1.宿泊施設における 2.お客様の安全確保について 3.衛生管理について 4.施設管理について 5.環境対応について 安 全 衛 生 管 理 そ の 他 基 礎 知 識 安全衛生管理その他基礎知識について 3.衛生管理について 4.施設管理について 5.環境対応について 2.お客様の安全確保について 宿泊施設におけるリスクの 1.',null,'[]'::jsonb),
('宿泊分野（1号）','環境対応として正しいのはどれですか？','["省エネ・節水・ゴミ削減", "使い捨てを増やす", "水を大量に使う", "冷暖房を最大にする"]'::jsonb,0,'SDGsの観点から環境にやさしい取り組みが重要です。',116,'1号 · 05 · 安全衛生管理','1号',46,'明していきます リスクの理解と回避について 1.宿泊施設における 2.お客様の安全確保について 3.衛生管理について 4.施設管理について 5.環境対応について 安 全 衛 生 管 理 そ の 他 基 礎 知 識 安全衛生管理その他基礎知識について 3.衛生管理について 4.施設管理について 5.環境対応について 2.お客様の安全確保について 宿泊施設におけるリスクの 1. 理解と回避について そ',null,'[]'::jsonb),
('宿泊分野（1号）','衛生管理で気をつけるべきものはどれですか？','["食中毒や感染症", "予約数", "料金", "客室数"]'::jsonb,0,'食中毒・感染症を発生させない衛生管理が重要です。',117,'1号 · 05 · 安全衛生管理','1号',49,'3.衛生管理について 宿泊施設においては、食中毒、感染症などを発生させぬよう、衛生管理を適切に行うこと がとても重要です。具体的には、 ・常に清潔なユニフォームを着用するとともに、頭髪や爪など身だしなみを衛生的な状 態に保つ ・うがいや手洗いは普段から習慣づける ・香りの強い香水は使って接客してはいけ',null,'[]'::jsonb),
('宿泊分野（1号）','火災を発見したときの対応として正しいのはどれですか？','["初期消火と避難誘導", "エレベーターで移動", "その場で待つ", "記録を書く"]'::jsonb,0,'初期消火とお客様の避難誘導を行います。',118,'1号 · 05 · 安全衛生管理','1号',47,'備えておくこと ・お客様の安全を確保するための機器類（火災報知器、消火器、客室からの避難具など） の場所と使い方を正しく理解しておくこと ・非常口とそこへ向かうための非常通路を常に確認し、お客様に正確に案内することが できること ・急病人の発生、事故、火災などの緊急事態について、各宿泊施設の定めた対応マニュ アルを正しく理解し、実行することができること ・病気や伝染病に関してその危険性や感染の広が',null,'[]'::jsonb),
('宿泊分野（1号）','従業員の安全確保として正しいのはどれですか？','["体調不良は上司に連絡して休む", "無理して働く", "黙って続ける", "休憩なしで働く"]'::jsonb,0,'体調が悪いときは上司に伝えて休むことが重要です。',119,'1号 · 05 · 安全衛生管理','1号',47,'具体的には、宿泊施設で働く従業員は、 リスクの理解と回避について ・火災や地震に関する避難訓練に参加し､万一の場合のお客様の安全確保に備えておくこと ・お客様の安全を確保するための機器類（火災報知器、消火器、客室からの避難具など） の場所と使い方を正しく理解しておくこと ・非常口とそこへ向かうための非常通路を常に確認し、お客様に正確に案内するこ',null,'[]'::jsonb),
('宿泊分野（1号）','電話対応で正しいのはどれですか？','["お客様が切ってから切る", "先に切る", "切らずに放置する", "子機を置くだけ"]'::jsonb,0,'お客様が受話器を置いたのを確認してから切ります。',120,'1号 · 01 · フロント業務','1号',14,'お客様がご滞在中にフロントに電話があった際は、話している内容が聞き取りやすいよう に、はっきりとゆっくり話すよう心がけます。また、お客様との電話を切る際には、必ず、 お客様が電話を切ってから電話を切るようにします。',null,'[]'::jsonb);
